	//
	// Required permissions:
	//   - `policy.read`
	GetLegalAndSupportSettings(context.Context, *connect.Request[v2.GetLegalAndSupportSettingsRequest]) (*connect.Response[v2.GetLegalAndSupportSettingsResponse], error)
	// Get Lockout Settings
	//
	// Get the lockout settings for the requested context.
	// This can be the instance or an organization. In case of an organization,
	// the returned settings will fall back to the instance settings if not explicitly set on the organization.
	//
	// Lockout settings define how many failed attempts are allowed before a user is locked out.
	//
	// Required permissions:
	//   - `policy.read`
	GetLockoutSettings(context.Context, *connect.Request[v2.GetLockoutSettingsRequest]) (*connect.Response[v2.GetLockoutSettingsResponse], error)
	// Get Security Settings
	//
	// Get the security settings of the ZITADEL instance.
	// Security settings include settings like enabling impersonation and embedded iframe settings.
	//
	// Required permissions:
	//   - `iam.policy.read`
	GetSecuritySettings(context.Context, *connect.Request[v2.GetSecuritySettingsRequest]) (*connect.Response[v2.GetSecuritySettingsResponse], error)
